    {
      "indice": 3,
      "atendido": true,
      "evidencia": "A cooperativa deve suspender a intermediação de frango caipira..."
    },
    {
      "indice": 4,
      "atendido": true,
      "evidencia": "...até que o produtor obtenha o registro junto ao SIE municipal... até a regularização"
