      "indice": 6,
      "atendido": true,
      "evidencia": "O relatório de inspeção da ADAGRO estabelece que os ovos não exigem SIE para venda direta ao consumidor"
    },
    {
      "indice": 7,
      "atendido": false,
      "evidencia": "A resposta omitiu a menção sobre a ausência de certificação orgânica."
    },
    {
      "indice": 8,
      "atendido": true,
      "evidencia": "[fonte: certificacoes/inspecao_adagro_2026.txt]"
    }
